import json, re, sys
sys.path.insert(0, "/workspace/third_party/python")
from inspect_ai.scorer._common import match_str

def remove_boxed(s):
    return re.sub(r"\\boxed\{(.+)\}", r"\1", s)

def score_text(text, gt):
    if "</think>" not in text:
        return 0, "no_think"
    ans = text.split("</think>")[-1]
    if len(ans.strip())==0:
        return 0, "empty"
    try:
        extracted, ok = match_str(remove_boxed(ans), str(gt), location="end", numeric=True)
    except Exception as e:
        return 0, f"exc {e}"
    return (1 if ok else 0), extracted

# disagreement analysis on closed responses step 1 and 5
for step in (1,5):
    rows=[json.loads(l) for l in open(f"/workspace/outputs/grpo/rollouts/{step}.jsonl")]
    mism=0
    examples=[]
    acc1_fail_reason=0
    # recompute
    for r in rows:
        sc, ext = score_text(r["output"], r["gts"])
        if sc != r["acc"]:
            mism+=1
        if r["acc"]==0 and "</think>" in r["output"]:
            ans=r["output"].split("</think>")[-1]
